"use client";
import { useState } from "react";
import { AnimatedCircularProgressBar } from "../magicui/AnimatedCircularProgressBar";
import { DemoFrame } from "../shared/DemoFrame";

export default function Demo() {
  const [value, setValue] = useState(64);
  return (
    <DemoFrame
      hint={value === 100 ? "All set. Ready for the next idea." : "Sample upload progress"}
    >
      <AnimatedCircularProgressBar
        value={value}
        gaugePrimaryColor="#0088ff"
        gaugeSecondaryColor="var(--border)"
      />
      <div className="flex gap-3">
        <button
          className="demo-action"
          disabled={value === 100}
          onClick={() => setValue(Math.min(100, value + 12))}
        >
          Advance
        </button>
        <button className="demo-action" onClick={() => setValue(0)}>
          Reset
        </button>
      </div>
    </DemoFrame>
  );
}

/** Example and adapters: Copyright (c) 2026 NikroZorkin. MIT; licenses/elements.txt. */
import type { ReactNode } from "react";

/** Layout for this example only. The component itself has no catalog dependency. */
export function DemoFrame({
  children,
  className = "",
  hint,
}: {
  children: ReactNode;
  className?: string;
  hint?: string;
}) {
  return (
    <div
      className={`relative flex min-h-[420px] w-full flex-col items-center justify-center gap-7 overflow-hidden p-8 ${className}`}
    >
      {children}
      {hint && (
        <p className="text-center text-xs text-muted-foreground" role="status">
          {hint}
        </p>
      )}
    </div>
  );
}

