  background: var(--foreground);
  color: var(--background);
  padding: 10px 20px;
  font-size: 14px;
}
.demo-action:disabled {
  cursor: not-allowed;
  opacity: 0.4;
}
.section-example {
  min-height: 420px;
  width: 100%;
}
.section-example > section > div {
  min-height: 0;
  padding-top: 48px;
  padding-bottom: 48px;
}
.section-example h1 {
  font-size: 40px;
}
.section-example h2 {
  font-size: 30px;
}
.section-example p {
  text-wrap: pretty;
}
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    scroll-behavior: auto !important;
    transition-duration: 0.01ms !important;
  }
}

